const rows = $input.all().map(item => item.json);

if (rows.length !== 1000) {
  throw new Error(
    `Expected 1000 reviews, received ${rows.length}`
  );
}

const required = [
  "review_id",
  "review_date",
  "rating",
  "cleaned_review_text",
  "source",
  "quote_eligible"
];

for (const field of required) {
  if (!Object.hasOwn(rows[0], field)) {
    throw new Error(`Missing required column: ${field}`);
  }
}

const ids = new Set();
let duplicateIds = 0;
let invalidRows = 0;

for (const row of rows) {
  const id = String(row.review_id ?? "").trim();
  const rating = String(row.rating ?? "").trim();
  const text = String(row.cleaned_review_text ?? "").trim();
  const date = new Date(row.review_date);

  if (!id || !text || !/^[1-5]$/.test(rating) || !Number.isFinite(date.getTime())) {
    invalidRows++;
    continue;
  }

  if (ids.has(id)) {
    duplicateIds++;
  }
  ids.add(id);
}

if (duplicateIds > 0 || invalidRows > 0) {
  throw new Error(
    `Validation failed: ${duplicateIds} duplicates, ` +
    `${invalidRows} invalid rows`
  );
}

return [{
  json: {
    product: "Groww",
    reviews_received: rows.length,
    unique_review_ids: ids.size,
    duplicate_ids: duplicateIds,
    invalid_rows: invalidRows,
    validation_passed: true,
    validated_at: new Date().toISOString(),
  },
}];

const validation = $input.first().json;

if (validation.validation_passed !== true) {
  throw new Error("Dataset validation must pass first");
}

const rows = $("Get row(s) in sheet")
  .all()
  .map(item => item.json);

if (rows.length !== 1000) {
  throw new Error(`Expected 1000 reviews, got ${rows.length}`);
}

const ids = new Set();

for (const row of rows) {
  const id = String(row.review_id ?? "");
  if (!id || !String(row.cleaned_review_text ?? "").trim()) {
    throw new Error("Missing review ID or review text");
  }
  if (ids.has(id)) {
    throw new Error(`Duplicate review ID: ${id}`);
  }
  if ("original_review_text" in row) {
    throw new Error("Private original review text found");
  }
  ids.add(id);
}

rows.sort((a, b) => String(a.review_id).localeCompare(String(b.review_id)));

const BATCH_SIZE = 25;
const TOTAL_BATCHES = 4;
const runId = `groww_100_test_${Date.now()}`;

const batches = [];
for (let i = 0; i < TOTAL_BATCHES; i++) {
  const subset = rows.slice(i * BATCH_SIZE, (i + 1) * BATCH_SIZE);
  const reviews = subset.map(r => ({
    review_id: String(r.review_id),
    review_date: String(r.review_date),
    rating: Number(r.rating),
    cleaned_review_text: String(r.cleaned_review_text),
    quote_eligible: String(r.quote_eligible),
    pii_redacted: String(r.pii_redacted)
  }));
  batches.push({
    json: {
      run_id: runId,
      batch_id: `test_batch_${i + 1}`,
      batch_index: i + 1,
      review_count: 25,
      review_ids: reviews.map(r => r.review_id),
      reviews,
      scope: "phase_3_2_initial_test",
      source_dataset: "analysis_sample_1000"
    },
    pairedItem: { item: { mode: "passThrough" } },
  });
}
return batches;

