const responses = $input.all();
if (responses.length !== 4) throw new Error("Expected 4 Gemini responses");
const expectedIds = new Set();
const seenIds = new Set();
const allowedThemes = new Set(["T1","T2","T3","T4","T5"]);
const allowedSentiments = new Set(["positive","negative","neutral","mixed","unclear"]);
const allowedFees = new Set(["brokerage","dp_charges","other_fee","unspecified_fee","none","unclear"]);
const themeCounts = {T1:0,T2:0,T3:0,T4:0,T5:0};

for (const item of responses) {
  const text = item.json.content?.parts?.map(p => p.text ?? "").join("");
  if (!text) throw new Error("Missing Gemini response text");
  const result = JSON.parse(text.trim().replace(/^```json\s*/i,"").replace(/\s*```$/,""));
  if (!Array.isArray(result.classifications) || result.classifications.length !== 25) {
    throw new Error("Batch does not contain 25 classifications");
  }
  for (const c of result.classifications) {
    if (!expectedIds.has(c.review_id)) throw new Error(`Unknown review ID ${c.review_id}`);
    if (seenIds.has(c.review_id)) throw new Error(`Duplicate review ID ${c.review_id}`);
    seenIds.add(c.review_id);
    for (const t of c.theme_ids || []) {
      if (!allowedThemes.has(t)) throw new Error(`Invalid theme ${t}`);
      themeCounts[t]++;
    }
    if (!allowedSentiments.has(c.sentiment)) throw new Error(`Invalid sentiment ${c.sentiment}`);
    if (!allowedFees.has(c.fee_topic)) throw new Error(`Invalid fee topic ${c.fee_topic}`);
  }
}
return [{ json: { total_classified: seenIds.size, theme_counts: themeCounts, validation_passed: true } }];

const d = $input.first().json;
return [{ json: {
  weekly_pulse: d.weekly_pulse || "",
  explanation_bullets: d.explanation_bullets || [],
  source_links: d.source_links || [],
  last_checked: d.last_checked || new Date().toISOString(),
  approval_status: "pending",
  quote_verification_pending: true,
} }];

const raw = $input.first().json.content?.parts?.[0]?.text;
if (!raw) throw new Error("Missing Gemini draft output");
const draft = JSON.parse(raw);
const words = draft.weekly_pulse.trim().split(/\s+/).length;
if (words > 250 || draft.explanation_bullets.length > 6) {
  throw new Error("Report length limits exceeded");
}
return [{ json: draft }];

