const crypto = require('crypto');
const draft = $input.first().json;
const payload = JSON.stringify({weekly_pulse: draft.weekly_pulse, fee_explainer: draft.explanation_bullets, source_links: draft.source_links, last_checked: draft.last_checked, product: "Groww"}, null, 2);
const payloadHash = crypto.createHash('sha256').update(payload).digest('hex');
const runId = draft.run_id ?? `groww_approval_${Date.now()}`;
const now = new Date().toISOString();
const approvalRecord = {run_id: runId, product: "Groww", payload_hash: payloadHash, payload_json: payload, approval_state: "approved", approved_at: now, actions: {append_to_doc: {status: "not_run", at: null}, create_email_draft: {status: "not_run", at: null}}};
return [{ json: { run_id: runId, payload_hash: payloadHash, payload_json: payload, approval_record: approvalRecord, approval_state: "approved", approved_at: now } }];
